const data = $input.first().json;

// Form submission field names
const member1Name = data["Member 1 Name"] || null;
const member1Location = data["Member 1 Current Location"] || null;
const member1Country = data["Member 1 Country"] || null;
const member1From = data["Member 1 Available From"] || null;
const member1Until = data["Member 1 Available Until"] || null;
const member1Visa = data["Member 1 Visa Permissions"] || "";

const member2Name = data["Member 2 Name"] || null;
const member2Location = data["Member 2 Current Location"] || null;
const member2Country = data["Member 2 Country"] || null;
const member2From = data["Member 2 Available From"] || null;
const member2Until = data["Member 2 Available Until"] || null;
const member2Visa = data["Member 2 Visa Permissions"] || "";

const joiningPreference = data["Joining Preference"] || "Any feasible route";

const members = [];

if (member1Name && member1Location && member1Country) {
  members.push({
    member_id: 1,
    member_name: member1Name,
    origin_city: member1Location,
    origin_country: member1Country,
    available_from: member1From,
    available_until: member1Until,
    visa_permissions: member1Visa
      ? member1Visa.split(",").map(v => v.trim()).filter(Boolean)
      : []
  });
}

if (member2Name && member2Location && member2Country) {
  members.push({
    member_id: 2,
    member_name: member2Name,
    origin_city: member2Location,
    origin_country: member2Country,
    available_from: member2From,
    available_until: member2Until,
    visa_permissions: member2Visa
      ? member2Visa.split(",").map(v => v.trim()).filter(Boolean)
      : []
  });
}

if (!members.length) {
  throw new Error("At least one UTM member is required.");
}

return [{
  json: {
    members,
    joining_preference: joiningPreference,
    form_submission_status: "UTM_MEMBER_DETAILS_RECEIVED"
  }
}];

const sessionRows = $input.all();

if (!sessionRows.length) {
  throw new Error(
    'No UTM form session was returned from the Data Table.'
  );
}

// Get the newest session returned by Get Active UTM Form Session
const sessions = sessionRows
  .map(item => item.json)
  .filter(row => row.project_id);

if (!sessions.length) {
  throw new Error(
    'No valid UTM project session was found.'
  );
}

// Newest session first
sessions.sort((a, b) => {
  const dateA = new Date(a.created_at || 0).getTime();
  const dateB = new Date(b.created_at || 0).getTime();

  return dateB - dateA;
});

const session = sessions[0];

// Get the actual submitted members
const formData = $('Prepare Submitted UTM Members').first().json;

const members = formData.members || [];

if (!members.length) {
  throw new Error(
    'No UTM members were submitted through the form.'
  );
}

// Recover joining options from the session
let joiningOptions = session.joining_options;

if (typeof joiningOptions === 'string') {
  try {
    joiningOptions = JSON.parse(joiningOptions);
  } catch (error) {
    throw new Error(
      'The joining_options stored in VSL UTM Form Sessions is not valid JSON.'
    );
  }
}

if (!Array.isArray(joiningOptions) || !joiningOptions.length) {
  throw new Error(
    'No joining options were found in the project session.'
  );
}

return [{
  json: {
    project_id: session.project_id,

    vessel_name: session.vessel_name,

    utm_date_requested: session.utm_date_requested,

    members: members,

    joining_options: joiningOptions,

    joining_preference:
      formData.joining_preference ||
      'Any feasible route',

    route_mode: 'CURRENT_LOCATION',

    context_status: 'PROJECT_CONTEXT_ATTACHED'
  }
}];

const context = $('Build Current Location Project Context').first().json;

if (!context.vessel_name) {
  throw new Error('Vessel name missing from project context.');
}

if (!context.utm_date_requested) {
  throw new Error('UTM requested date missing from project context.');
}

if (!Array.isArray(context.members) || !context.members.length) {
  throw new Error('No UTM members found.');
}

if (!Array.isArray(context.joining_options) || !context.joining_options.length) {
  throw new Error('No joining options found.');
}

return [{
  json: {
    project_id: context.project_id,
    vessel_name: context.vessel_name,
    utm_date_requested: context.utm_date_requested,
    members: context.members,
    joining_options: context.joining_options,
    joining_preference: context.joining_preference || 'Any feasible route',
    route_mode: 'CURRENT_LOCATION'
  }
}];
